intermediate.code:
db.users.createIndex({ email: 1 }, { unique: true })

try {
  await db.collection('users').insertOne({ email: 'a@example.com' })
} catch (e) {
  // handle duplicate key error
}

db.posts.createIndex({ tags: 1 })
// Query can use the index for any matching tag
db.posts.find({ tags: 'mongodb' })

db.orders.createIndex({ tenantId: 1, status: 1, createdAt: -1 })

// Can use the same index efficiently
db.orders.find({ tenantId: 't1', status: 'open' }).sort({ createdAt: -1 })

db.events.createIndex({ tenantId: 1, type: 1, createdAt: -1 })
// Good prefix use
db.events.find({ tenantId: 't1' })
// Poor use of the same index
db.events.find({ type: 'click' })

